package app.flameproject.weather.domain.model

import kotlinx.serialization.Serializable

/**
 * Extracted basic physical condition descriptions.
 */
@Serializable
data class AiBasicConditions(
    val temperature: String = "",
    val humidity: String = "",
    val wind: String = "",
    val pressure: String = "",
    val precipitation: String = ""
)

/**
 * Actionable living and transit advice generated by the AI model.
 */
@Serializable
data class AiAdvice(
    val clothing: String = "",
    val sun: String = "",
    val outdoor: String = "",
    val carWash: String = "",
    val umbrella: String = ""
)

/**
 * Complete structured analysis payload returned to the UI.
 */
@Serializable
data class AiAnalysisResult(
    val basic: AiBasicConditions = AiBasicConditions(),
    val advice: AiAdvice = AiAdvice(),
    val providerName: String = "",
    val modelName: String = ""
)

/**
 * Connection probe response metrics.
 */
data class AiConnectionTestResult(
    val isSuccess: Boolean,
    val latencyMs: Long,
    val errorMessage: String? = null
)

/**
 * Stable identifiers for failures that need a localized user-facing message.
 */
object AiErrorKeys {
    const val MISSING_API_KEY = "missing_api_key"
    const val CONNECTION_FAILED = "connection_failed"
    const val ANALYSIS_FAILED = "analysis_failed"
    const val UNPARSEABLE = "unparseable_output"
}

/**
 * Progress events emitted while the model answer is being produced.
 */
sealed interface AiStreamEvent {
    data class Delta(val text: String) : AiStreamEvent
    data class Retry(val attempt: Int) : AiStreamEvent
    data class Completed(val result: AiAnalysisResult) : AiStreamEvent
    data class Failed(val error: Throwable) : AiStreamEvent
}

/**
 * Extracts already-received fields from a partially streamed JSON answer.
 */
object AiPartialParser {

    private val fieldPattern = Regex(
        "\"(clothing|sun|outdoor|carWash|umbrella|temperature|humidity|wind|pressure|precipitation)\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)"
    )

    fun extract(text: String): Map<String, String> {
        val fields = mutableMapOf<String, String>()
        fieldPattern.findAll(text).forEach { match ->
            val value = unescape(match.groupValues[2])
            if (value.isNotBlank()) fields[match.groupValues[1]] = value
        }
        return fields
    }

    private fun unescape(raw: String): String = raw
        .replace("\\\"", "\"")
        .replace("\\\\", "\\")
        .replace("\\n", "\n")
        .replace("\\t", "\t")
}